import{_ as t,o as h,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Hiểu một đứa trẻ là việc có cấu trúc","description":"","frontmatter":{},"headers":[],"relativePath":"learner/index.md","filePath":"learner/index.md"}'),o={name:"learner/index.md"};function c(g,n,e,r,u,l){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="hieu-mot-đua-tre-la-viec-co-cau-truc" tabindex="-1">Hiểu một đứa trẻ là việc có cấu trúc <a class="header-anchor" href="#hieu-mot-đua-tre-la-viec-co-cau-truc" aria-label="Permalink to &quot;Hiểu một đứa trẻ là việc có cấu trúc&quot;">​</a></h1><p>Trên trang này# Hiểu một đứa trẻ là việc có cấu trúc <a href="#hieu-mot-đua-tre-la-viec-co-cau-truc">​</a> Câu &quot;hiểu học sinh&quot; thường được nói như một phẩm chất — người thầy tinh ý thì hiểu, người vô tâm thì không. Ở quy mô hàng nghìn learner, nó phải là một hệ thống: quan sát cái gì, kết luận thế nào, và chắc chắn tới đâu. Nemo12 tách việc này thành bốn tầng, và ranh giới giữa chúng là điều quan trọng nhất trong toàn bộ kiến trúc: text</p><h2 id="bon-khai-niem-bon-cau-hoi-khac-nhau-​" tabindex="-1">Bốn khái niệm, bốn câu hỏi khác nhau <a href="#bon-khai-niem-bon-cau-hoi-khac-nhau">​</a> <a class="header-anchor" href="#bon-khai-niem-bon-cau-hoi-khac-nhau-​" aria-label="Permalink to &quot;Bốn khái niệm, bốn câu hỏi khác nhau [​](#bon-khai-niem-bon-cau-hoi-khac-nhau)&quot;">​</a></h2><p><a href="/learner/evidence"><strong>Evidence</strong>Chuyện gì đã thật sự quan sát được? &quot;Sai 4/5 câu, hơn 3 phút mỗi câu, dùng gợi ý 3 lần.&quot; Không có kết luận nào ở đây.</a><a href="/learner/learner-model"><strong>Learner Model</strong>Từ những quan sát đó, learner hiện đang ở đâu? Mỗi mảng kiến thức một mức vững, kèm độ chắc chắn.</a><a href="/learner/context-model"><strong>Learner Context Model</strong>Đang có chuyện gì xảy ra quanh con lúc này? Sắp thi, đang ốm, tuần này chỉ có 30 phút mỗi ngày.</a><a href="/learner/confidence"><strong>Confidence Score</strong>Hệ thống tin vào kết luận của chính mình tới mức nào? Con số này quan trọng ngang kết luận.</a></p><h2 id="vi-sao-phai-tach-quan-sat-khoi-ket-luan-​" tabindex="-1">Vì sao phải tách quan sát khỏi kết luận <a href="#vi-sao-phai-tach-quan-sat-khoi-ket-luan">​</a> <a class="header-anchor" href="#vi-sao-phai-tach-quan-sat-khoi-ket-luan-​" aria-label="Permalink to &quot;Vì sao phải tách quan sát khỏi kết luận [​](#vi-sao-phai-tach-quan-sat-khoi-ket-luan)&quot;">​</a></h2><p>Đây là quy tắc gốc: <strong>hệ thống lưu quan sát, không lưu nhãn</strong>. Ghi <em>&quot;yếu đại số&quot;</em> là ghi một kết luận. Sáu tháng sau khi learner đã tiến bộ, cái nhãn vẫn nằm đó, và không ai biết nó từng dựa trên cái gì để mà xét lại. Tệ hơn, nếu cách đánh giá của hệ thống thay đổi, không có cách nào tính lại quá khứ. Ghi <em>&quot;ngày 3/9, sai 4/5 câu phân tích đa thức, dùng gợi ý 3 câu&quot;</em> là ghi một sự thật. Sự thật không hết hạn. Kết luận rút ra từ nó có thể được tính lại bất cứ lúc nào, bằng thuật toán mới, và toàn bộ lịch sử vẫn dùng được. Hệ quả thực tế cho gia đình: <strong>mọi kết luận Nemo12 đưa ra đều truy ngược được về những quan sát cụ thể đã tạo ra nó</strong>. Không có &quot;hệ thống nói con yếu phần này&quot; mà không kèm được lý do.</p><h2 id="bon-tang-khong-tang-nao-lan-tang-nao-​" tabindex="-1">Bốn tầng, không tầng nào lấn tầng nào <a href="#bon-tang-khong-tang-nao-lan-tang-nao">​</a> <a class="header-anchor" href="#bon-tang-khong-tang-nao-lan-tang-nao-​" aria-label="Permalink to &quot;Bốn tầng, không tầng nào lấn tầng nào [​](#bon-tang-khong-tang-nao-lan-tang-nao)&quot;">​</a></h2><p>Một quy tắc nghe nhỏ nhưng có hệ quả lớn: <strong>con ốm không làm mức vững của con giảm</strong>. Ốm là chuyện xảy ra <em>quanh</em> learner, không phải bằng chứng về việc learner biết gì. Nó thuộc Context Model, và nó đổi <strong>gợi ý học hôm nay</strong> — chứ không đụng tới Learner Model. Sau khi khỏi, không có gì phải &quot;khôi phục&quot; cả, vì không có gì bị hạ. Nghe hiển nhiên, nhưng rất nhiều hệ thống làm sai chỗ này: điểm kém tuần con ốm bị trộn thẳng vào đánh giá năng lực, và ba tháng sau không ai nhớ vì sao đường biểu diễn lại sụt ở đó.</p><h2 id="he-thong-luon-noi-ro-minh-chua-biet-gi-​" tabindex="-1">Hệ thống luôn nói rõ mình chưa biết gì <a href="#he-thong-luon-noi-ro-minh-chua-biet-gi">​</a> <a class="header-anchor" href="#he-thong-luon-noi-ro-minh-chua-biet-gi-​" aria-label="Permalink to &quot;Hệ thống luôn nói rõ mình chưa biết gì [​](#he-thong-luon-noi-ro-minh-chua-biet-gi)&quot;">​</a></h2><p>Ba trạng thái sau <strong>hoàn toàn khác nhau</strong>, và Nemo12 không bao giờ gộp chúng: Trạng tháiNghĩa làNên làm gì<strong>Chưa học</strong>Con chưa từng gặp phần nàyHọc từ đầu<strong>Chưa đủ bằng chứng</strong>Có thể con biết, hệ thống chưa dám kết luậnĐo thêm, đừng bắt học lại<strong>Đã đo, chưa vững</strong>Có bằng chứng rõ là con còn hụtHọc lại phần cụ thể đang hụtGộp ba trạng thái này thành một ô trống trên bảng tiến độ là cách nhanh nhất để bắt một đứa trẻ học lại thứ nó đã biết. <a href="/learner/mot-bai-test-khong-du">Vì sao một bài test không đủ để hiểu một learner →</a> Hệ thống không được phép nói &quot;tôi hiểu con bạn&quot;. Nó chỉ được nói &quot;đây là những gì tôi quan sát được, đây là kết luận tôi rút ra, và đây là mức tôi tin vào kết luận đó&quot;.</p>',10)])])}const k=t(o,[["render",c]]);export{s as __pageData,k as default};
